import {renderArchiveVersions,managedArchiveSummary} from './packages/design-prepared-ui/archive-view.mjs';
import {createPreparedWorkflowController,preparedUnmappedNotes,parsePreparedEntryValue,preparedComparisonPair,preparedSynthesisEvidence,preparedManagedViewCoverage,applicationViewCoverage} from './packages/design-prepared-ui/controller.mjs';
import {DESIGN_PHASES,DESIGN_ZONES} from './packages/analysis-engine/design-pilot.mjs';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const angleNames={front:'正面',back:'背面',left:'左侧',right:'右侧'},assessmentNames={limited_evidence:'证据不足，不能形成完整三视图结论',potential_conflict:'逐角度判断存在潜在冲突，需复核',consistent_judgments:'现有逐角度判断方向一致，不代表达标',mixed_judgments:'逐角度判断不一致，保留各自限制'};
const zoneNames=['刘海','顶区','耳前','耳后','中区','底区'],steps=['素材原话','人物与备注','六区工艺','完成复盘','档案候选'];
const phaseNames=['剪前基础','拟执行方案','实际执行','完成复盘','已归档'];
const noteNames={style:'风格',person:'人物',length:'长度',features:'特点',layers:'层次',bangs:'刘海',curls:'卷度',care:'完成后打理'};
const fieldNames={requested_style:'风格意向',self_description:'员工记录的自述',visible_outline:'轮廓描述（需核查）',visible_hair_shape:'发型形态描述（需核查）',rod_type:'杠具',rod_size_mm:'杠径',rod_method:'卷杠方法',direction:'方向',angle_degrees:'角度',turns:'圈数',product:'产品',formula:'配方',mixture:'配比',application:'涂放',softening_check:'软化现场记录',time_minutes:'时间',temperature_celsius:'温度',color_target:'目标颜色',color_formula:'染色配方',observed_result:'员工观察的完成情况',model_photo_comparison_front:'正面 AI完成照比较（模型原判未确认 / 非执行事实）',model_photo_comparison_back:'背面 AI完成照比较（模型原判未确认 / 非执行事实）',model_photo_comparison_left:'左侧 AI完成照比较（模型原判未确认 / 非执行事实）',model_photo_comparison_right:'右侧 AI完成照比较（模型原判未确认 / 非执行事实）',model_completion_synthesis_left:'正面 / 背面 / 左侧 AI判断综合（推断，非执行事实）',model_completion_synthesis_right:'正面 / 背面 / 右侧 AI判断综合（推断，非执行事实）',customer_feedback:'记录的反馈',employee_review:'员工复盘'};
for(const angle of ['front','back','left','right']){fieldNames['managed_before_outline_'+angle]='托管剪前'+angleNames[angle]+'轮廓（待核查）';fieldNames['managed_before_hair_shape_'+angle]='托管剪前'+angleNames[angle]+'发型形态（待核查）';fieldNames['managed_photo_comparison_'+angle]='托管'+angleNames[angle]+'完成照比较（非执行事实）';}for(const side of ['left','right'])fieldNames['managed_completion_synthesis_'+side]='托管'+angleNames[side]+'三视图判断综合（推断）';
const serviceFields={perm:['rod_type','rod_size_mm','rod_method','direction','angle_degrees','turns','product','formula','mixture','application','softening_check','time_minutes','temperature_celsius'],dye:['color_target','color_formula','product','mixture','application','time_minutes','temperature_celsius'],cut:['direction','angle_degrees']};
const option=(value,label,selected)=>`<option value="${E(value)}"${value===selected?' selected':''}>${E(label)}</option>`;
export function mountPreparedDesign(container,{enabled=false,adapter,recorder,previews,customers=[]}={}){
  const controller=createPreparedWorkflowController({enabled,adapter,recorder,previews});let view=controller.view(),step=0,zone='top',destroyed=false;const drafts=new Map(),hidden=new Set();
  const draft=()=>{if(!drafts.has(view.selected))drafts.set(view.selected,{});return drafts.get(view.selected);};
  const value=name=>E(draft()[name]||'');
  let texts=[];
  const raw=value=>{const index=texts.push(String(value??''))-1;return `<span data-raw="${index}"></span>`;};
  function textarea(name,label,key=name){return `<label>${E(label)}<textarea name="${name}" data-draft="${E(key)}" maxlength="12000"></textarea></label>`;}
  function sources(){return view.native.sources.map(s=>`<article class="apw-source"><span class="apw-meta">${E(s.messageId)} · ${['synthetic_image_description','synthetic_application_comparison','synthetic_application_synthesis'].includes(s.kind)&&s.actor==='system'?'合成演练 mock 描述，未调用真实模型，非员工原话':s.kind==='server_synthesis'&&s.actor==='system'?'服务器整理既有AI判断，未调用新模型、非员工原话':s.kind==='model_synthesis'&&s.actor==='model'?'模型综合推断，未重新看图、非员工原话':s.kind==='image_description'&&s.actor==='model'?'模型视觉描述，待核查非测量':s.kind==='speech_transcript'?'转写文本，未证明准确性':s.actor==='employee'?'员工记录原文':'来源 '+E(s.actor)+' / '+E(s.kind)}</span><pre>${raw(s.text)}</pre></article>`).join('');}
  function sourceSelect(ns){return `<label>引用原文<select name="sourceId" data-draft="${E(ns)}.sourceId">${view.native.sources.filter(s=>!['model_synthesis','server_synthesis','synthetic_image_description','synthetic_application_comparison','synthetic_application_synthesis'].includes(s.kind)).map(s=>option(s.messageId,s.messageId,draft()[ns+'.sourceId'])).join('')}</select></label>`;}
  function entryForm(category,group){const ns='entry.'+(group?.groupId||category);const fields=category==='context'?['requested_style','self_description','visible_outline','visible_hair_shape']:category==='review'?['observed_result','customer_feedback','employee_review']:serviceFields[group.service];return `<form data-command="record_${category}" ${group?`data-group="${E(group.groupId)}"`:''}><label>明确归入字段<select name="field" data-draft="${E(ns)}.field">${fields.map(f=>option(f,fieldNames[f],draft()[ns+'.field'])).join('')}</select></label>${group?`<label>计划 / 实际<select name="track" data-draft="${E(ns)}.track">${option('planned','拟执行',draft()[ns+'.track'])}${option('actual','实际记录',draft()[ns+'.track'])}</select></label>`:''}${textarea('entryValue','值（逐字来源；留空表示未知；数值字段仅数字，不推断单位）',ns+'.value')}${sourceSelect(ns)}${textarea('entryQuote','逐字引文',ns+'.quote')}<button type="submit">归入待核对卡片</button></form>`;}
  function privatePhotoPairs(){
    if(!view.canPhonePhotos)return '';
    const refs=view.record.photoRefs.filter(p=>p.kind!=='legacy_asset').map(p=>p.reference);
    return `<section class="adp-card" data-private-photo-pairs><h3>剪前 / 完成后照片复核</h3><p>按记录的角度并排查看；标签不保证姿态、光线或距离可比。每张照片需单独核权预览，员工观察另行记录并确认。</p>${['front','back','left','right'].filter(angle=>refs.some(p=>p.angle===angle)).map(angle=>`<section data-private-pair="${angle}"><h4>${E(angleNames[angle])}</h4><div class="apw-private-pair">${['before','after'].map(stage=>`<section><strong>${stage==='before'?'剪前':'完成后'}</strong>${refs.filter(p=>p.stage===stage&&p.angle===angle).map(p=>{const preview=view.previewItems.find(v=>v.mediaId===p.mediaId);return `<figure><figcaption class="apw-meta">${E(p.mime)}</figcaption>${preview?`<img class="apw-preview" src="${E(preview.url)}" alt="${E(angleNames[angle])} · ${stage==='before'?'剪前':'完成后'} · 私有预览">`:'<p>尚未读取照片</p>'}<button data-action="preview" data-media-id="${E(p.mediaId)}"${view.previewBusy||view.uploadBusy?' disabled':''}>重新核权并预览</button></figure>`;}).join('')||'<p>未附此角度照片</p>'}</section>`).join('')}</div></section>`).join('')}</section>`;
  }
  function synthesisDetails(syn){const focusLabels={missing_views:'补齐缺失角度',noncomparable_views:'核查不可比较原因',opposing_judgments:'核查相反判断',cross_view_differences:'核查跨角度差异',confirm_angle_judgment:'核查尚未确认的逐角度判断',capture_conditions:'核查拍摄条件'};return `<div data-synthesis-evidence><p data-synthesis-generation>${syn.generation==='deterministic'?'服务器整理既有AI判断：未调用新模型，不产生本次模型费用。':'模型选择优先复核重点：既有判断与缺失 / 不可比 / 冲突范围由服务器固定。'}</p><p data-synthesis-focus>优先复核：${syn.reviewFocus?E(focusLabels[syn.reviewFocus.kind]||syn.reviewFocus.kind)+' · '+E(syn.reviewFocus.angles.map(a=>angleNames[a]).join('、')):'无额外重点'}；不是新视觉证据或员工原话。</p><p><strong>${E(assessmentNames[syn.assessment]||syn.assessment)}</strong>；综合已采纳逐角度AI判断，没有重新看图。</p><p>明确侧面：${E(angleNames[syn.side])}，不代表另一侧。缺失：${E(syn.missingAngles.map(a=>angleNames[a]).join('、')||'无')}；不可比较：${E(syn.uncomparableAngles.map(a=>angleNames[a]).join('、')||'无')}；潜在冲突：${E(syn.conflictingAngles.map(a=>angleNames[a]).join('、')||'无')}。</p>${syn.evidence.map(e=>`<article data-synthesis-angle="${E(e.angle)}"><p>${E(angleNames[e.angle])} · 逐角度模型判断 · ${e.entryStatus==='confirmed'?'该条已记录员工确认':'该条未确认'}</p><pre>${raw(e.judgment.change??'无法比较：'+e.judgment.reason)}</pre><p class="apw-meta">祖先候选 ${E(e.candidateId)} · 原条目 ${E(e.entryId)}</p></article>`).join('')}<details><summary>完整逐角度来源、采纳身份与限制（原样）</summary><pre>${raw(JSON.stringify(syn,null,2))}</pre></details></div>`;}
  function entryCard(entry){
    const normalizedSource=entry.sources.some(ref=>view.native.sources.some(s=>s.messageId===ref.messageId&&['synthetic_image_description','synthetic_application_comparison','synthetic_application_synthesis'].includes(s.kind)));
    const modelSource=entry.sources.some(ref=>view.native.sources.some(s=>s.messageId===ref.messageId&&(s.actor==='model'||s.kind==='server_synthesis')));
    const syntheses=(view.record.modelCandidates||[]).map(row=>row.candidate).filter(c=>c.kind==='completion_synthesis'&&c.descriptionSources.some(s=>entry.sources.some(ref=>ref.messageId===s.messageId)));
    const comparisons=(view.record.modelCandidates||[]).map(row=>row.candidate).filter(c=>c.kind==='completion_comparison'&&c.descriptionSources.some(s=>entry.sources.some(ref=>ref.messageId===s.messageId)));
    const managedEntries=view.record.schemaVersion==='design-workflow-view-v1'?(view.record.acceptedCandidates||[]).filter(c=>c.evidenceSummary&&c.entries.some(e=>e.id===entry.id)):view.record.managedImageHistory?managedArchiveSummary(view.record.managedImageHistory).accepted.filter(c=>c.evidenceSummary&&c.entries.some(e=>e.id===entry.id)):[],managedSynthesis=managedEntries.find(c=>c.kind==='managed_completion_synthesis');
    return `${normalizedSource?`<p data-normalized-origin>${E(NORMALIZED_SYNTHETIC_NOTICE)}</p>`:''}${modelSource?`<p>${managedSynthesis?(managedSynthesis.evidenceSummary.generation==='deterministic'?'服务器本地整理既有判断，非新视觉证据':'模型只选择复核重点，没有重新看图'):syntheses.length?'整理已采纳逐角度AI判断，没有重新看图；属于综合推断':'模型视觉描述，待核查非测量'}；员工确认不等于客观测量或执行事实。</p>`:''}<p><strong>${E(fieldNames[entry.field]||entry.field)}</strong>：${entry.value===null?'待确认':E(entry.value)} <small>${entry.status==='confirmed'?'已由服务端记录员工确认':'未确认'}</small></p>${entry.sources.map(s=>`<div class="apw-meta">${view.native.sources.some(source=>source.messageId===s.messageId&&['synthetic_image_description','synthetic_application_comparison','synthetic_application_synthesis'].includes(source.kind))?'合成 mock 描述引文（非员工原话）':view.native.sources.some(source=>source.messageId===s.messageId&&(source.actor==='model'||source.kind==='server_synthesis'))?'AI判断整理来源引文（非员工原话）':'原话'}：${raw(s.quote)}</div>`).join('')}${managedEntries.map(c=>`<details data-accepted-managed-view><summary>已采纳逐角来源与限制 · ${E(c.kind)}</summary>${managedViewEvidence(c.evidenceSummary,c.kind)}<p>这里保留采纳时的依据，不自动重算、重新生成或改变当前员工确认。</p></details>`).join('')}${comparisons.map(c=>`<details data-accepted-comparison><summary>本条比较的两张来源 · ${E(c.comparison.angle)}</summary><p>剪前 ${E(c.comparison.beforeMediaId)} → 完成后 ${E(c.comparison.afterMediaId)}；仅引用，不自动读取图片。</p><pre>${raw(JSON.stringify(c.sourceRefs,null,2))}</pre></details>`).join('')}${syntheses.map(c=>{const current=preparedSynthesisEvidence(view.record,c.synthesis.side),evidence=c.synthesis.evidence.map(({judgment,...ref})=>ref);const stale=!current||current.evidence.length!==evidence.length||current.evidence.some((ref,i)=>Object.keys(ref).some(k=>ref[k]!==evidence[i]?.[k]));return `<details data-accepted-synthesis><summary>综合依据与限制 · ${E(angleNames[c.synthesis.side])} · 原生修订 ${c.baseRevision}</summary>${synthesisDetails(c.synthesis)}<details><summary>全部私有照片引用与摘要（原样）</summary><pre>${raw(JSON.stringify(c.sourceRefs,null,2))}</pre></details></details>${stale?'<p data-synthesis-stale>当前逐角度证据或确认状态已变化；这是当时的综合，请重新核查。不会自动再次调用模型。</p>':''}`;}).join('')}<div class="apw-meta">${E(entry.id)}</div>`;
  }
  function neutral(){return `<div class="apw-neutral">${['正面','侧面','背面'].map((label,i)=>`<figure><svg viewBox="0 0 160 170" role="img" aria-label="${label}中性分区示意"><path d="M55 130v18l-27 17h104l-27-17v-18" fill="#d7d2ca"/><ellipse cx="80" cy="83" rx="47" ry="61" fill="#e5dfd4"/><path d="M39 73q3-53 41-54 40 2 41 54" fill="#b6c3b0"/><path d="M35 72v37q10 30 45 34 35-4 45-34V72" fill="none" stroke="#b9a78e" stroke-width="9"/><path d="M46 58h68M43 95h74M54 124h52" stroke="#fff" stroke-width="2"/><text x="80" y="16" text-anchor="middle" font-size="10">${label}</text><text x="80" y="84" text-anchor="middle" font-size="11">${zoneNames[DESIGN_ZONES.indexOf(zone)]}</text></svg></figure>`).join('')}</div><p class="apw-meta">仅中性分区示意，不显示未经证实的角度、旋转或不对称几何。</p>`;}
  function normalizedSyntheticPanel(){
    if(!view.canNormalizedSynthetic||view.canApplicationContent)return '';
    const n=view.normalizedSynthetic,c=n.candidate,blocked=n.busy||n.pending||view.native.phase!=='before_analysis',names={not_found:'未找到原请求，结果仍未核实；不会重新提交',pending:'请求待核查，尚未返回完成候选',uncertain:'结果不确定，请仅核查原请求',completed:'已读取合成候选；尚未采纳或确认'};
    return `<section class="adp-card" data-normalized-synthetic><h3>规范化图片 · 合成演练候选</h3><p data-normalized-notice>${E(NORMALIZED_SYNTHETIC_NOTICE)}</p><p>这里只接受服务端已有任务编号作为查询选择，不上传图片、不用浏览器声明其合格，也不把旧验证状态当作发送许可。服务端须逐次核查独立任务、当前身份、图片版本及原请求账本。</p><label>服务端任务编号（尚待服务端核权）<input data-normalized-task data-draft="normalizedTask" value="${value('normalizedTask')}" maxlength="100" autocomplete="off"></label><button data-action="normalized-describe"${blocked?' disabled':''}>明确生成本次合成候选</button>${view.native.phase!=='before_analysis'?'<p>仅剪前阶段可请求这一合成演练，不自动恢复阶段。</p>':''}<label>原请求编号（刷新后手动恢复）<input data-normalized-request-id data-draft="normalizedRequest" value="${value('normalizedRequest')}" maxlength="100" autocomplete="off"></label><button data-action="normalized-check"${n.busy?' disabled':''}>仅查询原请求（不重新生成）</button>${n.requestId?`<p data-normalized-request>原请求 ${E(n.requestId)}。请保存编号，关闭或刷新不会取消服务器请求。</p>`:''}${n.busy?'<p role="status" data-normalized-busy>正在核查合成请求。</p>':''}${n.status?`<p data-normalized-state>${E(names[n.status.state])}</p>`:''}${n.error?`<p role="alert" data-normalized-error>${E(n.error.code)}；结果不确定时只查询原编号，不新建请求。</p>`:''}${n.pending?'<button data-action="normalized-abandon">明确停止本页追踪（不取消服务端请求）</button>':''}${n.unresolved.map(item=>`<p data-normalized-unresolved>未核实原请求 ${E(item.requestId)}，不代表取消或未执行。</p>`).join('')}${c?`<section data-normalized-review><p>合成候选 ${E(c.id)} · ${E(angleNames[c.sourceSummary.angle])} · 原记录 revision ${c.workflowRevision}</p><p data-normalized-versions>来源版本 ${E(c.sourceSummary.sourceVersion)} / 托管父版本 ${E(c.sourceSummary.parentVersion)} / 规范化版本 ${E(c.sourceSummary.normalizedVersion)}。固定夹具资格不适用于真实客户。</p>${c.candidate.warnings.map(w=>`<p>${E(w)}</p>`).join('')}<form data-command="accept_normalized_candidate">${c.candidate.entries.map((entry,index)=>`<label><input type="checkbox" data-normalized-index="${index}"> ${E(fieldNames[entry.field]||entry.field)}：${entry.value===null?'未知（null）':E(entry.value)} · ${entry.status==='unknown'?'未知':'未确认'}</label>`).join('')}<button type="submit"${n.busy||n.pending?' disabled':''}>明确采纳所选合成条目（不等于确认）</button></form><p>采纳只加入待核对来源。需要在人物卡片另行提交员工核查原话；它仍不是实际操作记录。</p></section>`:''}</section>`;
  }
  function durableSynthesisPanel(){
    if(!view.canDurableSynthesis)return '';
    const op=view.synthesisOperation,names={queued:'已入队，尚未完成',leased:'处理中，尚未确认外发',dispatch_claimed:'已领取外发资格，可能已发送',completed:'处理已完成，采纳与确认仍独立',uncertain:'执行结果不确定，不能当作未发送',not_sent:'服务端报告未发送',cancelled:'服务端确认在外发前取消'};
    return `<section data-durable-synthesis><p>耐久任务模式：提交回执仅表示已受理，不表示综合已完成。页面不自动轮询或重新生成；关闭、返回、切换顾客只停止本页显示，不取消服务端任务。</p>${view.synthesisRequestId?`<p data-synthesis-request>待核查原请求 ${E(view.synthesisRequestId)}。刷新页面后请用“读取本次服务任务”恢复，不重新提交。</p>`:''}<button data-action="synthesis-list"${view.modelBusy||view.synthesisListBusy?' disabled':''}>读取本次服务任务（恢复）</button>${view.synthesisListBusy?'<p role="status">正在重新核权读取任务。</p>':''}${op?`<article data-synthesis-operation><p>任务 ${E(op.id)} · 原请求 ${E(op.requestId)} · ${E(angleNames[op.side])}</p><p data-synthesis-operation-state>${E(names[op.state])}${op.cancelRequested?'；已请求停止后续执行，但不能撤回已发送请求或保证不收费':''}</p><p>来源：记录 revision ${op.sourceBinding.workflowRevision} / 原生 ${op.sourceBinding.sessionRevision}。${op.sourceBinding.workflowRevision!==view.record.revision?'当前记录已变化，旧结果不可直接采纳。':''}</p><p>${op.resultAvailable?'候选已发布，可重新核权读取；发布不等于已加入记录或员工已确认。':'当前未返回可供核查的候选；不能据此认定没有执行或没有费用。'}</p><button data-action="synthesis-check"${view.modelBusy?' disabled':''}>核查当前任务（不重新生成）</button>${!['completed','not_sent','cancelled'].includes(op.state)?`<button data-action="synthesis-cancel"${view.modelBusy?' disabled':''}>请求停止后续执行（不撤回已发送请求）</button>`:''}</article>`:''}${view.synthesisOperations.length?'<p data-synthesis-list-note>下列是上次查询的任务快照，不代表实时状态。请重新读取或逐项核查。</p>':''}${view.synthesisOperations.map(item=>`<article data-synthesis-recovery><p>${E(names[item.state])} · ${E(angleNames[item.side])} · 记录 revision ${item.sourceBinding.workflowRevision}</p><p>任务 ${E(item.id)} · 原请求 ${E(item.requestId)}</p><button data-action="synthesis-resume" data-operation-id="${E(item.id)}"${view.modelBusy?' disabled':''}>重新核权查看此任务</button></article>`).join('')}</section>`;
  }
  function modelPanel(completion=false){
    const synthesis=completion==='synthesis',title=synthesis?'三视图判断综合候选':completion?'完成照片比较候选':'模型整理候选';
    if(!view.canModel||synthesis&&!view.canSynthesize||completion&&!synthesis&&!view.canCompare)return `<section class="adp-card"><h3>${title}</h3><p>尚未配置，未读取或外发照片、未发模型请求。员工原话与手动复盘仍可独立使用。</p></section>`;
    const acceptedKinds=synthesis?['completion_synthesis']:completion?['completion_comparison']:['text_extraction','visual_description'];const c=view.modelCandidate&&acceptedKinds.includes(view.modelCandidate.kind)?view.modelCandidate:null;const operationKind=synthesis?'synthesize':completion?'compare':null,activeOperation=operationKind?view.modelOperationKind===operationKind:['extract','vision'].includes(view.modelOperationKind);
    const disabled=view.modelBusy||view.modelPending||view.native.phase==='archive',refs=view.record.photoRefs.filter(p=>p.kind==='private_media').map(p=>p.reference);
    const pair=preparedComparisonPair(view.record,draft().comparisonBefore,draft().comparisonAfter);
    const coverage=synthesis?preparedSynthesisEvidence(view.record,draft().synthesisSide):null;
    const controls=synthesis?`<p>综合当前已采纳的正面、背面及明确一侧AI比较判断，不会重新读取或外发照片。即使逐角度条目已由员工确认，也不是测量或操作因果证据。</p><label>明确选择侧面（不代表另一侧）<select data-model-side data-draft="synthesisSide"${disabled?' disabled':''}>${option('','请选择左侧或右侧',draft().synthesisSide||'')}${option('left','左侧',draft().synthesisSide)}${option('right','右侧',draft().synthesisSide)}</select></label>${coverage?`<p data-synthesis-coverage>当前可用已采纳比较：${coverage.evidence.map(e=>angleNames[e.angle]).join('、')||'无'}；缺失：${coverage.missingAngles.map(a=>angleNames[a]).join('、')||'无'}。一至两角度只能形成明确不足的综合；不能补猜缺失或抹掉不可比 / 冲突。</p>`:'<p>不默认选择侧面。先逐角度采纳比较，才有综合依据。</p>'}<button data-action="model-synthesize"${disabled||view.native.phase!=='completed_review'||!coverage?.evidence.length?' disabled':''}>明确整理已采纳AI判断</button>`:completion?`<p>只比较本次已附的剪前 / 完成后同角度照片。模型输出仅为有限视觉判断，非测量、执行事实、化学因果或达标证明。计划与实际工艺保持原记录，不从照片推断。</p><div class="apw-tracks">${[['before','剪前','comparisonBefore'],['after','完成后','comparisonAfter']].map(([stage,label,key])=>`<label>${label}照片引用<select data-model-${stage} data-draft="${key}">${option('','请选择明确照片',draft()[key]||'')}${refs.filter(r=>r.stage===stage&&['front','back','left','right'].includes(r.angle)).map(r=>option(r.mediaId,r.mediaId+' · '+r.angle,draft()[key])).join('')}</select></label>`).join('')}</div><p>${pair?'已选择同一明确角度：'+E(pair.angle):'请选择两个不同、同角度的剪前与完成后私有引用；detail、参考照或角度不同不比较。'}</p><button data-action="model-compare"${disabled||view.native.phase!=='completed_review'||!pair?' disabled':''}>明确请求完成照片比较（需独立许可）</button>${view.native.phase!=='completed_review'?'<p>请先明确进入完成复盘阶段；剪前不生成完成比较。</p>':''}`:
      `<button data-action="model-extract"${disabled?' disabled':''}>请求原话提取候选</button>${view.canVision?`<label>仅选本次已附私有引用<select data-model-media>${refs.map(r=>option(r.mediaId,r.mediaId+' · '+r.stage+' / '+r.angle)).join('')}</select></label><button data-action="model-vision"${disabled||view.native.phase!=='before_analysis'||!refs.length?' disabled':''}>请求基础外形视觉候选（需独立许可）</button>`:'<p>视觉处理许可未配置，不读取或外发照片。</p>'}`;
    return `<section class="adp-card apw-model-review"${synthesis?' data-synthesis-review':completion?' data-comparison-review':''}><h3>${title} · 需要人工核查</h3><p>${synthesis?'服务端按可用复核重点决定本地整理或经独立批准调用模型。具体方式以返回候选为准；不会重新看图，均不自动确认。':'仅明确操作才申请服务端本次外发 / 费用许可。原话提取与模型视觉描述分开，均不自动确认为事实或实际操作。'}</p>${controls}${synthesis?durableSynthesisPanel():''}${view.modelBusy&&activeOperation?`<p role="status">${synthesis&&view.canDurableSynthesis?'正在提交或核查任务，不自动重发。':'正在请求候选，不自动重试。'}</p>`:''}${view.modelError&&activeOperation?`<p role="alert">${E(view.modelError)}。${synthesis&&view.canDurableSynthesis?'只核查原任务，不重新提交。上下文变化的旧结果不可采纳；查询暂无结果不代表任务未执行。':'上下文变更的候选不可采纳；需重新核查，再明确请求，不会自动再次调用模型。'}</p>`:''}${view.modelPending&&!view.modelBusy&&activeOperation?`<p>${synthesis&&view.canDurableSynthesis?'任务回执或结果待核查，只查询原请求，不重新提交；查询无结果也不会重发。':'模型请求结果待核查，保留原请求身份，不新建付费请求。'}</p><button data-action="model-retry">${synthesis&&view.canDurableSynthesis?'查询原任务（不重新生成）':'核查后重试同一候选请求'}</button><button data-action="model-abandon">停止本页重试，保留请求编号待核查</button>`:''}${(view.modelUnresolved||[]).filter(r=>operationKind?r.kind===operationKind:['extract','vision'].includes(r.kind)).map(r=>`<p data-model-unresolved>待核查原请求 ${E(r.requestId)}${r.candidateId?' / 候选 '+E(r.candidateId):''}；未取消服务端调用，不能据此认定未收费。另一次请求仍须服务端本次独立批准。</p>`).join('')}${c?`<div data-model-candidate><h4>${c.kind==='completion_synthesis'?(c.synthesis.generation==='deterministic'?'服务器整理既有AI判断，未确认，未重新看图':'模型选择优先复核重点，未确认，未重新看图'):c.kind==='completion_comparison'?'模型完成照视觉判断，未确认、非测量或执行事实':c.kind==='visual_description'?'模型视觉描述，待核查非测量':'原话提取候选，尚未加入记录'}</h4><p>候选 ${E(c.id)} · 基于原生修订 ${c.baseRevision}</p>${c.synthesis?synthesisDetails(c.synthesis):''}${c.comparison?`<p data-comparison-pair>剪前 ${E(c.comparison.beforeMediaId)} → 完成后 ${E(c.comparison.afterMediaId)} · ${E(c.comparison.angle)}；实际复盘位置不代表证明执行过某工艺。</p>`:''}${c.sourceRefs.map(ref=>`<p>私有图片来源：${E(ref.mediaId)}；仅引用，不加载图片。</p>`).join('')}${c.sourceRefs.length?`<details><summary>来源引用与完整性摘要（不是授权证明）</summary><pre>${raw(JSON.stringify(c.sourceRefs,null,2))}</pre></details>`:''}${c.descriptionSources.map(s=>`<article data-model-source><p>${E(s.messageId)} · ${E(s.kind)} / ${E(s.actor)}；${s.kind==='server_synthesis'?'服务器整理来源，未调用新模型':'模型来源'}，不是员工原话。</p><pre>${raw(s.text)}</pre></article>`).join('')}<form data-command="accept_model_candidate">${c.candidate.entries.map((entry,i)=>`<article><label><input type="checkbox" data-model-index="${i}">选择条目 ${i+1}</label><p>${E(entry.category)} / ${E(entry.groupId??'无组')} / ${E(entry.side??'不适用')} / ${E(entry.track)} / ${E(entry.field)} · ${E(entry.basis||'依据未提供')}</p><pre>${raw(entry.value===null?'未知（null），不补造值':typeof entry.value==='string'?entry.value:JSON.stringify(entry.value))}</pre><p>原状态 ${E(entry.status)}，加入后仍须独立员工核对。</p>${(entry.sources||[]).map(source=>`<p>${c.descriptionSources.some(s=>s.messageId===source.messageId)?'候选来源逐字引用（非员工原话）':'原话逐字引用'} · ${E(source.messageId)}</p><pre>${raw(source.quote)}</pre>`).join('')}</article>`).join('')}<button${view.busy||view.pending?' disabled':''}>加入待核对记录</button></form>${(c.candidate.warnings||[]).map(w=>`<p>${raw(w)}</p>`).join('')}</div>`:''}</section>`;
  }
  function managedModelPanel(){
    if(!view.canManagedModels)return '';const m=view.managedModel||{},v=m.verification,c=m.candidate;
    const states={pending_validation:'照片仍在等待安全检查，不能请求分析',validation_failed:'照片安全检查未通过，不能请求分析',evidence_complete:'服务器返回技术证据完整；仍需单独核查本次分析许可'};
    const outcomes={not_found:'未查到原请求，不代表之前没有执行；不会重新发送',pending:'原请求仍在处理，尚无可采纳结果',uncertain:'原请求结果未知，不能当作没有发送或没有费用',completed:'候选已发布，尚未加入记录或由员工确认'};
    return `<section class="adp-card apw-managed-model" data-managed-model><h3>照片分析候选（合成验收）</h3><p>只整理剪前可见的基础外形，不分析打理，不推断工艺。当前演示不代表真实托管服务或解码器已验收。</p><label>已知检查任务编号<input data-managed-task data-draft="managedTask" value="${value('managedTask')}" maxlength="100"></label><button data-action="managed-verification"${m.busy||m.pending?' disabled':''}>查询安全检查结果</button>
    ${v?`<p data-managed-verification>${E(states[v.state])}</p><details><summary>查看本次来源</summary><p>照片 ${E(v.mediaId)} · 源版本 ${E(v.sourceVersion)} · 检查任务 ${E(v.taskId)}</p><p>技术证据不等于允许外发、付费或员工确认；此结果不是持续授权。</p></details>`:''}
    <button data-action="managed-describe"${m.busy||m.pending||view.busy||view.pending||view.native.phase!=='before_analysis'||v?.state!=='evidence_complete'?' disabled':''}>请求基础外形候选（仍需独立许可）</button>
    ${m.busy?'<p role="status">正在核查当前请求，不自动重发。</p>':''}${m.status?`<p data-managed-model-state>${E(outcomes[m.status.state])}</p>`:''}${m.error?`<p role="alert" data-managed-model-error>${E(m.error.code)}。本次未返回可用结果，请核查原请求，不要重复发送。</p>`:''}
    ${m.requestId?`<p data-managed-model-request>原请求 <code>${E(m.requestId)}</code>。关闭或切换只隐藏本页，不取消服务器请求。</p>`:''}
    <details><summary>按原请求编号恢复查询</summary><label>请求编号<input data-managed-model-request-id data-draft="managedModelRequest" value="${value('managedModelRequest')}" maxlength="100"></label><p>刷新后只按已知编号查询；本页不保存令牌、照片或请求到浏览器存储。</p></details><button data-action="managed-model-check"${m.busy?' disabled':''}>查询原请求（不重新生成）</button>
    ${m.pending&&!m.busy?'<button data-action="managed-model-abandon">停止在本页追踪此请求（不取消执行）</button>':''}${(m.unresolved||[]).map(r=>`<p>未核实原请求 ${E(r.requestId)}，不能认定未发送或未收费。</p>`).join('')}
    ${c?`<div data-managed-model-candidate><h4>模型视觉描述，未确认、非测量或员工原话</h4><p>候选 ${E(c.id)} · 原生修订 ${c.baseRevision}。不会据此填写烫染参数、打理或实际操作。</p><form data-command="accept_managed_candidate">${c.candidate.entries.map((entry,i)=>`<article><label><input type="checkbox" data-managed-model-index="${i}">选择条目 ${i+1}</label><p>${E(fieldNames[entry.field])} · ${E(entry.status)}</p><pre>${raw(entry.value??'未知，不补猜')}</pre>${entry.sources.map(source=>`<p>模型来源 ${E(source.messageId)}，非员工原话：</p><pre>${raw(source.quote)}</pre>`).join('')}</article>`).join('')}<button${view.busy||view.pending?' disabled':''}>加入待核对记录</button></form><p>采纳后仍未确认；员工确认必须另作明确操作。</p>${c.candidate.warnings.map(w=>`<p>${raw(w)}</p>`).join('')}</div>`:''}</section>`;
  }
  function managedViewEvidence(summary,kind){
    if(kind==='managed_application_completion_comparison'){return `<div data-application-comparison-evidence><p>同角${E(angleNames[summary.angle])}：剪前 ${E(summary.before.mediaId)} → 完成后 ${E(summary.after.mediaId)}</p><p>${raw(summary.judgment.change??'无法比较：'+summary.judgment.reason)}</p><p>仅合成 mock 视觉判断，非测量，不证明工艺、药水、达标或因果；原图与规范化图使用应用清单引用，不是原生版本。</p></div>`;}
    if(kind==='managed_application_completion_synthesis'){return `<div data-application-synthesis-evidence><p>仅综合已采纳的合成比较，不重复发送图片。${summary.generation==='deterministic'?'确定性整理，未调用模型。':'mock 选择复核重点，未调用真实模型。'}</p>${synthesisDetails(summary)}<p>缺角、不可比、未确认均保留；综合建议不等于事实或工艺。</p></div>`;}
    if(kind==='managed_application_before_view'){const v=summary.view;return `<div data-application-accepted-evidence><p>应用私有原图 → 规范化 PNG · ${E(angleNames[v.angle])} · 照片编号 ${E(v.mediaId)}</p><p>仅固定合成样例的 mock 描述，未调用真实模型；不适用于真实顾客。只对应记录的拍摄方向，不证明工艺、药水、打理或实际执行。</p><p>应用清单保留原图与规范化对象关联，不是原生存储版本或新的分析许可。</p></div>`;}
    const source=v=>`<p>${v.stage==='before'?'剪前':'完成后'} ${E(angleNames[v.angle])} · 任务 ${E(v.taskId)} · 源版本 ${E(v.sourceVersion)} · 衍生版本 ${E(v.normalizedVersion??v.derivativeVersion??'不适用')}</p>`;
    if(['managed_before_view','managed_normalized_before_view','managed_visual_description','visual_description'].includes(kind))return `<div data-managed-view-evidence>${source(summary.view)}<p>只对应这个记录的拍摄方向，不代表其它角度；未检查打理、工艺或药水。</p></div>`;
    if(['managed_completion_comparison','completion_comparison'].includes(kind))return `<div data-managed-view-evidence>${source(summary.before)}${source(summary.after)}<p>${raw(summary.judgment.change??'无法比较：'+summary.judgment.reason)}</p><p>视觉对照不是测量，不证明实际工艺、达标或因果。</p></div>`;
    if(!['managed_completion_synthesis','completion_synthesis'].includes(kind))return '<p>此来源摘要类型暂不支持展示；保留原记录，不按综合证据解释。</p>';
    const labels={missing_views:'补齐缺失角度',noncomparable_views:'核查不可比较原因',opposing_judgments:'核查相反判断',cross_view_differences:'分别核查跨角度差异',confirm_angle_judgment:'核查尚未确认的逐角判断',capture_conditions:'核查拍摄条件'};
    return `<div data-managed-view-evidence><p data-managed-view-generation>${summary.generation==='deterministic'?'服务器本地整理已采纳判断，本次未调用新模型。':'模型只选择优先复核重点，没有重新查看照片。'}</p><p>${E(assessmentNames[summary.assessment])}。明确采用${E(angleNames[summary.side])}，不代表另一侧。</p><p>缺角：${E(summary.missingAngles.map(a=>angleNames[a]).join('、')||'无')}；不可比：${E(summary.uncomparableAngles.map(a=>angleNames[a]).join('、')||'无')}；潜在冲突：${E(summary.conflictingAngles.map(a=>angleNames[a]).join('、')||'无')}。</p><p>逐角已确认：${E(summary.confirmedAngles.map(a=>angleNames[a]).join('、')||'无')}；逐角未确认：${E(summary.unconfirmedAngles.map(a=>angleNames[a]).join('、')||'无')}。保留原确认状态，不表示综合本身已确认、客观事实或新批准。</p>${summary.evidence.map(e=>`<article data-managed-view-ancestor><strong>${E(angleNames[e.angle])}</strong><p>${raw(e.judgment.change??'无法比较：'+e.judgment.reason)}</p><p>${e.entryStatus==='confirmed'?'已记录员工对该条的确认':'该条仍未确认'} · 祖先候选 ${E(e.candidateId)}</p></article>`).join('')}<p>优先复核：${summary.reviewFocus?E(labels[summary.reviewFocus.kind])+' · '+E(summary.reviewFocus.angles.map(a=>angleNames[a]).join('、')):'无额外重点'}。仅为推断整理，不证明工艺、药水、测量、达标或因果。</p></div>`;
  }
  function managedViewsPanel(){
    if(!view.canManagedViews)return '';const m=view.managedViews||{},tasks=m.tasks||[],c=m.candidate,side=draft().managedViewSide||'left',coverage=preparedManagedViewCoverage(view.record,side),completion=view.native.phase==='completed_review';
    const stateLabels={pending_validation:'待安全检查',validation_failed:'安全检查未通过',evidence_complete:'技术证据完整，仍需独立许可'},outcomes={not_found:'未查到原请求，不代表从未执行；不会重发',pending:'原请求仍在处理',uncertain:'结果未知，不代表未发送或免费',completed:'候选已发布，仍需明确采纳与独立确认'};
    const ready=tasks.filter(t=>t.state==='evidence_complete'),before=ready.filter(t=>t.stage==='before'),after=ready.filter(t=>t.stage==='after');
    const beforeId=draft().managedViewBefore||before[0]?.taskId,afterId=draft().managedViewAfter||after[0]?.taskId,b=before.find(v=>v.taskId===beforeId),a=after.find(v=>v.taskId===afterId),pair=b&&a&&b.angle===a.angle&&b.taskId!==a.taskId;
    const blocked=m.busy||m.pending||view.busy||view.pending,eligibleAncestors=coverage.comparisons.filter(v=>['front','back',side].includes(v.angle));
    return `<section class="adp-card" data-managed-views><h3>逐角照片与综合（合成验收）</h3><p>本次只用合成资料验收，不代表真实托管服务或解码器已获验收。技术检查不是外发、费用或员工确认许可。</p><label>已知检查任务编号<input data-managed-view-task data-draft="managedViewTask" value="${value('managedViewTask')}" maxlength="100"></label><button data-action="managed-view-verify"${blocked?' disabled':''}>查询并加入本页视角列表</button><p>列表是上次查询的快照，不是持续授权。重读或离开后按已知编号恢复，不保存到浏览器。</p><div data-managed-view-tasks>${tasks.map(t=>`<article><p>${t.stage==='before'?'剪前':'完成后'} · ${E(angleNames[t.angle])} · ${E(stateLabels[t.state])}</p><p>任务 ${E(t.taskId)} · 源 ${E(t.sourceVersion)} · 衍生 ${E(t.derivativeVersion)}</p>${t.stage==='before'?`<button data-action="managed-view-describe" data-task-id="${E(t.taskId)}"${blocked||t.state!=='evidence_complete'||view.native.phase!=='before_analysis'?' disabled':''}>请求${E(angleNames[t.angle])}基础外形候选</button>`:''}</article>`).join('')||'<p>尚无本页已查询任务。</p>'}</div>
    <section data-managed-view-coverage><h4>剪前已采纳视角</h4><label>明确侧面<select data-managed-view-side data-draft="managedViewSide">${['left','right'].map(a=>option(a,angleNames[a],side)).join('')}</select></label><p>${coverage.before.map(v=>E(angleNames[v.angle])+'（'+v.fields.map(e=>e.hasValue?'有待核查描述':'未知').join('、')+'）').join('；')||'尚未采纳逐角候选'}。缺少：${E(coverage.missingBefore.map(a=>angleNames[a]).join('、')||'无')}。方向齐全也不代表可比较或已确认。</p></section>
    ${completion?`<section><h4>同角剪前 / 完成照对照</h4><label>剪前任务<select data-managed-view-before data-draft="managedViewBefore">${before.map(t=>option(t.taskId,angleNames[t.angle]+' · '+t.taskId,beforeId)).join('')}</select></label><label>完成后任务<select data-managed-view-after data-draft="managedViewAfter">${after.map(t=>option(t.taskId,angleNames[t.angle]+' · '+t.taskId,afterId)).join('')}</select></label><button data-action="managed-view-compare"${blocked||!pair?' disabled':''}>请求此同角对照</button>${!pair?'<p>需两个不同任务，分别为剪前、完成后，且明确拍摄方向一致。</p>':''}<h4>独立三视图判断综合</h4><p>只整理服务器核实的已采纳逐角比较，不重新看图。当前可见比较：${coverage.comparisons.map(v=>E(angleNames[v.angle])).join('、')||'无'}。正面、背面与所选${E(angleNames[side])}缺角或不可比须原样保留。</p><button data-action="managed-view-synthesize"${blocked||!eligibleAncestors.length?' disabled':''}>请求整理已采纳逐角判断</button><p>服务器决定本地整理或经独立批准选择复核重点，不从缺角自行推断免费或模型必需。</p></section>`:''}
    ${m.busy?'<p role="status">正在核查原请求，不自动重发。</p>':''}${m.status?`<p data-managed-view-state>${E(outcomes[m.status.state])}</p>`:''}${m.error?`<p role="alert" data-managed-view-error>${E(m.error.code)}。未返回可用结果，请核查原编号；网络或许可失败不等于图片验证失败。</p>`:''}${m.requestId?`<p data-managed-view-request>原请求 <code>${E(m.requestId)}</code>。关闭或切换只停止本页显示，不取消服务器执行。</p>`:''}<details><summary>按原请求编号恢复查询</summary><label>请求编号<input data-managed-view-request-id data-draft="managedViewRequest" value="${value('managedViewRequest')}" maxlength="100"></label></details><button data-action="managed-view-check"${m.busy?' disabled':''}>查询原请求（不重新生成）</button>${m.pending&&!m.busy?'<button data-action="managed-view-abandon">停止本页追踪（不是取消）</button>':''}${(m.unresolved||[]).map(r=>`<p>未核实请求 ${E(r.requestId)}，可能已完成，不自动重试。</p>`).join('')}
    ${c?`<section data-managed-view-candidate><h4>${c.kind==='managed_before_view'?'本角度模型外形描述':c.kind==='managed_completion_comparison'?'本角度模型对照':'独立综合推断'} · 待核对</h4>${managedViewEvidence(c.evidenceSummary,c.kind)}<form data-command="accept_managed_view_candidate">${c.candidate.entries.map((e,i)=>`<article><label><input type="checkbox" data-managed-view-index="${i}">${E(fieldNames[e.field])} · ${E(e.status)}</label>${c.kind==='managed_before_view'?`<pre>${raw(e.value??'未知，不补猜')}</pre>`:'<p>选择这一结构化判断加入待核对记录，不替代人工观察。</p>'}</article>`).join('')}<button${blocked||!c.candidate.entries.length?' disabled':''}>加入待核对记录</button></form><p>发布不等于采纳，采纳不等于员工确认；实际操作与计划不从图片推断。</p></section>`:''}</section>`;
  }
  function applicationViewsPanel(){if(!view.canApplicationViews)return '';const v=view.applicationViews||{},tasks=v.tasks||[],stored=view.managed?.completed||[],side=draft().applicationViewSide||'left',coverage=applicationViewCoverage(view.record,side),before=tasks.filter(t=>t.source.stage==='before'),after=tasks.filter(t=>t.source.stage==='after'),bid=draft().applicationViewBefore||before[0]?.taskId,aid=draft().applicationViewAfter||after[0]?.taskId,b=before.find(t=>t.taskId===bid),a=after.find(t=>t.taskId===aid),pair=b&&a&&b.source.angle===a.source.angle&&b.taskId!==a.taskId,blocked=v.busy||v.pending||v.prepare||view.busy||view.pending,completion=view.native.phase==='completed_review';return `<section data-application-views><h3>同角比较与三视图综合 · 固定合成演练</h3><p>准备、比较与综合分别核权。仅本页已准备任务自动配对，不填写内部任务编号；准备成功不代表发送许可。</p>${stored.map(x=>`<p>${E(x.stage==='before'?'剪前':'完成后')} ${E(angleNames[x.angle])} · ${E(x.mediaId)} <button data-action="application-view-prepare" data-media-id="${E(x.mediaId)}"${blocked||tasks.some(t=>t.source.mediaId===x.mediaId&&t.source.reference.digest===x.source.digest)?' disabled':''}>${tasks.some(t=>t.source.mediaId===x.mediaId&&t.source.reference.digest===x.source.digest)?'本页已有任务选择（发送仍须核权）':'准备此视角供对比（独立许可）'}</button></p>`).join('')}${v.prepare?`<p>原视角准备请求 ${E(v.prepare.requestId)}</p><button data-action="application-view-prepare-status"${v.busy?' disabled':''}>仅查询原视角准备</button>`:''}<div data-application-view-tasks>${tasks.map(t=>`<p>${E(t.source.stage==='before'?'剪前':'完成后')} ${E(angleNames[t.source.angle])} 已准备，仅是核权快照。</p>`).join('')}</div>${completion?`<label>剪前已准备照片<select data-application-view-before data-draft="applicationViewBefore">${before.map(t=>option(t.taskId,angleNames[t.source.angle]+' · '+t.source.mediaId,bid)).join('')}</select></label><label>完成后已准备照片<select data-application-view-after data-draft="applicationViewAfter">${after.map(t=>option(t.taskId,angleNames[t.source.angle]+' · '+t.source.mediaId,aid)).join('')}</select></label><button data-action="application-view-compare"${blocked||!pair?' disabled':''}>明确比较同角剪前 / 完成后（需独立许可）</button>${!pair?'<p>必须选择同一个明确角度的剪前与完成后照片，不自动换图。</p>':''}<label>综合明确侧面<select data-application-view-side data-draft="applicationViewSide">${['left','right'].map(x=>option(x,angleNames[x],side)).join('')}</select></label><p data-application-view-coverage>已采纳比较：${coverage.comparisons.map(x=>E(angleNames[x.angle])+' · '+(x.entryStatus==='confirmed'?'员工已确认':'未确认')+(x.judgment.comparability==='not_comparable'?' · 不可比':'')).join('；')||'无'}。缺角：${E(coverage.missingAngles.map(x=>angleNames[x]).join('、')||'无')}。不补造缺失证据。</p><button data-action="application-view-synthesize"${blocked||!coverage.comparisons.length?' disabled':''}>明确综合已采纳判断（不重发图片）</button>`:'<p>比较与综合仅在完成复盘阶段开放，不自动推进阶段。</p>'}${v.pending?`<p>原比较 / 综合请求 ${E(v.pending.requestId)}，未知不重发。</p><button data-action="application-view-status"${v.busy?' disabled':''}>只查询原请求</button>`:''}${v.error?`<p role="alert">${E(v.error)}，只查询原请求。</p>`:''}${v.candidate?`<section data-application-view-review>${managedViewEvidence(v.candidate.evidenceSummary,v.candidate.kind)}${v.candidate.candidate.warnings.map(w=>`<p>${E(w)}</p>`).join('')}<form data-command="accept_application_view_candidate"><label><input type="checkbox" data-application-view-index="0">采纳此合成候选为待核查条目，不等于员工确认</label><button type="submit"${blocked?' disabled':''}>明确采纳比较 / 综合候选</button></form></section>`:''}</section>`;}
  function managedImagesPanel(){
    if(!view.canManagedImages)return '';const m=view.managed||{},s=m.status,application=view.canApplicationContent===true,a=view.application||{};
    return `<section class="adp-card apw-managed" data-managed-images><h3>照片安全检查</h3>${application?'<p data-application-synthetic>仅合成图片演练，不可上传真实顾客照片。应用级私有存储成功不代表解码验证或模型发送许可。</p>':'<p>照片仅保存到私有空间，通过检查前不能用于 AI 分析。</p>'}<p class="apw-meta" data-managed-size-limit>${application?'仅固定合成 JPEG 或 WebP':'JPEG、PNG 或 WebP'}，原图不超过 ${E(MANAGED_IMAGE_LIMIT_TEXT)}；不会自动压缩或修改照片。</p><label>选择照片（不自动上传）<input data-managed-file type="file" accept="${application?'image/jpeg,image/webp':'image/png,image/jpeg,image/webp'}"${m.busy||m.pending?' disabled':''}></label><div class="apw-tracks"><label>阶段<select data-managed-stage${m.selection||m.busy||m.pending?' disabled':''}>${[['before','剪前'],['after','完成后'],...(!application?[['reference','参考']]:[])].map(([v,t])=>option(v,t,m.selection?.stage??'before')).join('')}</select></label><label>角度<select data-managed-angle${m.selection||m.busy||m.pending?' disabled':''}>${[['front','正面'],['back','背面'],['left','明确左侧'],['right','明确右侧'],...(!application?[['detail','局部']]:[])].map(([v,t])=>option(v,t,m.selection?.angle??'front')).join('')}</select></label></div>
    ${m.selection?`<p data-managed-selected>已选择照片，尚未检查或上传。更改阶段或角度请先清除所选照片，再重新选择。</p><button data-action="managed-upload"${m.busy||m.pending?' disabled':''}>保存照片（需上传许可）</button><button data-action="managed-clear"${m.busy?' disabled':''}>清除所选照片</button>`:''}
    ${m.busy?'<p role="status">正在保存或查询照片状态，不自动重发。</p>':''}
    ${m.pending?'<p data-managed-unknown>上传结果暂不确定，请查询原照片编号，不要重复上传。</p>':''}
    ${s?`<p data-managed-state>${application?(s.state!=='stored'?'原上传尚未确认保存，不自动重发。':'原图已保存。保存本身不代表分析授权，以独立准备和发送状态为准。'):'照片已保存，等待安全检查，暂不能用于 AI 分析。'}</p>`:''}
    ${application&&m.pending?'<button data-action="application-reconcile">核对原对象并恢复回执（不重新上传）</button>':''}
    ${application&&(m.completed||[]).length?`<ul data-application-completed>${m.completed.map(x=>`<li>${E(x.stage)} / ${E(x.angle)} · ${E(x.mediaId)}：仅存储成功 <button data-action="application-prepare" data-media-id="${E(x.mediaId)}"${a.busy||a.prepare?' disabled':''}>准备合成分析（需独立许可）</button></li>`).join('')}</ul>`:''}
    ${application&&s?.state==='stored'&&!(m.completed||[]).some(x=>x.mediaId===s.mediaId)?`<button data-action="application-prepare" data-media-id="${E(s.mediaId)}"${a.busy||a.prepare?' disabled':''}>准备合成分析（需独立许可）</button>`:''}
    ${application&&a.prepare?`<p data-application-prepare-pending>准备请求 ${E(a.prepare.requestId)}，只能查询原请求，不自动重新处理。</p><button data-action="application-prepare-status"${a.busy?' disabled':''}>查询原准备请求</button>`:''}
    ${application&&a.prepared?`<p data-application-prepare-state>${a.prepared.state==='ready'?'准备已完成，模型生成是独立步骤；本次为合成 mock 演练，未调用真实模型。':a.prepared.state==='failed'?'独立验证未通过，不能分析。':'准备尚未确认完成。'}</p>`:''}
    ${application&&a.prepared?.state==='ready'?`<button data-action="application-model-describe"${a.busy||a.model?.pending||view.native.phase!=='before_analysis'?' disabled':''}>明确生成合成候选（需独立模型许可）</button>`:''}
    ${application&&a.model?.pending?`<p data-application-model-request>原模型请求 ${E(a.model.pending.requestId)}；不会重新发送。</p><button data-action="application-model-status"${a.busy?' disabled':''}>仅查询原模型请求</button>`:''}
    ${application&&a.candidate?`<section data-application-review><h4>合成候选，未确认、非实际操作</h4>${a.candidate.candidate.warnings.map(w=>`<p>${E(w)}</p>`).join('')}<form data-command="accept_application_candidate">${a.candidate.candidate.entries.map((entry,i)=>`<label><input type="checkbox" data-application-index="${i}">${E(fieldNames[entry.field]||entry.field)}：${entry.value===null?'未知':E(entry.value)} · 未确认</label>`).join('')}<button type="submit"${a.busy||a.model?.pending?' disabled':''}>明确采纳所选合成条目（不等于确认）</button></form></section>`:''}
    ${application&&a.error?`<p role="alert" data-application-error>${E(a.error)}。请只查询原请求，不重复发起。</p>`:''}
    ${m.error?`<p role="alert" data-managed-error>${E(application&&m.error.code==='MANAGED_FILE_INVALID'?'仅接受不超过 8 MiB 的固定合成 JPEG 或 WebP 样例。本次未上传，原有草稿保留。':managedImageErrorMessage(m.error))}</p>`:''}
    <button data-action="managed-status"${m.busy?' disabled':''}>查询照片状态</button><p class="apw-meta">查询不上传新照片，也不调用模型。</p>
    <details data-managed-details><summary>查看照片编号与检查详情</summary>
    ${m.mediaId?`<p data-managed-id>照片编号 <code>${E(m.mediaId)}</code>${m.requestId?` · ${m.pending?'待核查上传请求':'本次回执请求'} <code>${E(m.requestId)}</code>`:''}。请保留照片编号以便查询；本页不写浏览器存储。</p>`:''}
    ${m.selection?`<p>文件声明 ${E(m.selection.mime)} · ${m.selection.byteLength} bytes · ${E(m.selection.stage)} / ${E(m.selection.angle)}。未声称已解码。</p>`:''}
    ${s?`<p data-managed-detail-state>${application?`应用对象状态 ${E(s.state)}${s.source?` · 清单修订 ${s.source.revision}`:''}`:`${s.state==='quarantined'?'已保存隔离原图，尚未验证':'已保存变换回执，仍待技术验证'} · 源版本 ${E(s.sourceVersion)}`}</p><p>这是本次核权查询快照，不是实时状态。不可发送给模型、不可采纳为记录、不可公开预览。</p>`:''}
    ${m.error?`<p data-managed-error-detail>${E(m.error.code)}：${m.error.outcome==='not_sent'?'本次未交付可用结果':'请求结果未知，请先查询原编号'}。这不是图片技术验证失败的结论；不会据此重发。</p>`:''}
    ${application?`<label>原上传请求编号<input data-application-request data-draft="applicationRequest" value="${value('applicationRequest')}" maxlength="100"></label>`:''}<label>按已知照片编号恢复查询（仅当前服务）<input data-managed-lookup data-draft="managedLookup" value="${value('managedLookup')}" maxlength="100"></label><p class="apw-meta">原文件保存在私有隔离区。哈希、上传成功或变换回执都不证明完整解码、隐私清除或可供模型使用。关闭、切换或刷新会清除未发送字节和本页结果，不代表取消服务器请求。当前无全量恢复列表，关闭后需用已知编号查询；查无结果也不证明之前没有写入。服务器尚未返回可信验证失败摘要，页面不自行判断通过或失败。</p></details>${applicationViewsPanel()}</section>`;
  }
  function content(){
    if(step===0)return `<div class="apw-grid"><section class="adp-card"><h3>原话与文字转写</h3><form data-command="record_source"><label>来源类型<select name="kind"><option value="text">手工记录</option><option value="speech_transcript">已有语音转文字</option></select></label>${textarea('sourceText','原始文本，不自动解析')}<button>追加原文</button></form><button data-action="transcript">取得转写候选（需配置）</button>${view.transcript?`<p>转写候选，未确认：</p><pre data-transcript>${raw(view.transcript.text)}</pre><button data-action="accept-transcript">作为转写来源记录</button>`:''}${view.canRecord?`<section class="apw-capture"><p>录音：${E(view.captureStatus)}。仅显式操作才申请配置的音轨，不自动访问麦克风。</p><button data-action="record-start"${view.captureStatus!=='idle'||view.speechPending?' disabled':''}>开始本地录音</button><button data-action="record-stop"${view.captureStatus!=='recording'?' disabled':''}>停止录音</button><button data-action="record-cancel">取消并清除本地音频</button>${view.audio?`<p data-audio-ready>PCM16 单声道 ${view.audio.channelPolicy==='mix-to-mono'?'（显式本地混音）':''} ${(view.audio.durationMs/1000).toFixed(2)}秒 · ${view.audio.byteLength} bytes；尚未发送。</p><button data-action="record-submit"${view.speechPending||view.speechBusy?' disabled':''}>明确发送转写请求（需服务端授权）</button>`:''}${view.speechPending?'<p data-speech-pending>转写结果待核查，不自动重发，不写入实际操作。</p>':''}</section>`:'<p class="apw-meta">录音未配置，不启动麦克风、语音识别或录音。</p>'}</section><section class="adp-card"><h3>私有照片引用</h3>${view.canUpload?`<section><label>明确选择本地图片（不自动上传）<input data-photo-file type="file" accept="${view.canPhonePhotos?'image/png,image/jpeg,image/webp,image/heic,image/heif,.heic,.heif':'image/png,image/jpeg,image/webp'}"></label><label>阶段<select data-photo-stage><option value="before">剪前</option><option value="after">完成后</option><option value="reference">参考</option></select></label><label>角度<select data-photo-angle>${['front','back','left','right','detail'].map(a=>option(a,a)).join('')}</select></label>${view.photoUpload?`<p data-photo-ready>${view.photoUpload.pendingServerDecode?'已选择 HEIC/HEIF，将由私有服务端解码验证':'已本地解码'} ${view.photoUpload.byteLength} bytes，${E(view.photoUpload.stage)} / ${E(view.photoUpload.angle)}，尚未发送。</p><button data-action="photo-upload"${view.uploadBusy||view.previewBusy||view.uploadPending?' disabled':''}>明确授权上传私有图片</button>`:''}${view.uploadPending?`<p>上传结果待核查，不新建请求。</p><button data-action="photo-retry"${view.uploadBusy||view.previewBusy?' disabled':''}>核对后重试同一上传请求</button>`:''}${view.uploaded?`<p data-uploaded>后端返回私有引用 ${E(view.uploaded.mediaId)}</p><button data-action="photo-attach">核权后附入当前记录</button>`:''}</section>`:''}<form data-command="attach_media"><label>已授权私有媒体 ID<input name="mediaId" data-draft="mediaId" value="${value('mediaId')}" maxlength="100"></label><button>核验并附上引用</button></form><p class="apw-meta">引用不接受图片 URL。上传与预览均须独立授权，附入前由后端核查当前服务范围。</p>${view.record.photoRefs.map(p=>p.kind==='legacy_asset'?`<p data-media-ref>旧照片引用 ${E(p.assetId)} · ${E(p.stage)} / ${E(p.angle)}；仅元数据，未读取图片。</p>`:`<p data-media-ref>${E(p.reference.mediaId)} · ${E(p.reference.stage)} / ${E(p.reference.angle)} · ${E(p.reference.mime)}${view.canPreview?` <button data-action="preview" data-media-id="${E(p.reference.mediaId)}"${view.previewBusy||view.uploadBusy?' disabled':''}>核权并预览</button>`:''}</p>`).join('')}${view.previewItems.map(p=>`<figure><img class="apw-preview" src="${E(p.url)}" alt="${E(p.stage+' '+p.angle)} · 私有本地预览"><figcaption>本地临时预览，切换顾客即清除。</figcaption></figure>`).join('')}</section></div>${normalizedSyntheticPanel()}${managedImagesPanel()}${managedModelPanel()}${managedViewsPanel()}${modelPanel()}${sources()}`;
    if(step===1){const confirmable=view.native.entries.filter(e=>e.category==='person_style'&&e.value!==null&&e.status!=='confirmed');return `<div class="apw-grid"><section class="adp-card"><h3>八步原始备注 · 未映射</h3><p>原话完整保留，不把旧字段强行改成证据字段。剪前不提供打理分析。</p><form data-command="record_note"><label>备注字段<select name="field">${Object.entries(noteNames).filter(([key])=>key!=='care'||view.native.phase==='completed_review').map(([key,label])=>option(key,label)).join('')}</select></label>${textarea('noteText','原始备注')}<button>保留未映射备注</button></form>${preparedUnmappedNotes(view.record.session).map(n=>`<article data-unmapped><strong>${E(noteNames[n.field])} · 未映射</strong><pre>${raw(n.text)}</pre></article>`).join('')}</section><section class="adp-card"><h3>明确来源 → 基础卡片</h3>${entryForm('context')}${view.native.entries.filter(e=>e.category==='person_style').map(entryCard).join('')}${confirmable.length?`<form data-command="confirm_entry" data-context-confirm><label>独立核对基础条目<select name="entryId">${confirmable.map(e=>option(e.id,`${fieldNames[e.field]||e.field}: ${e.value}`)).join('')}</select></label>${textarea('confirmText','写明本人核对的值；不把模型描述改称测量或执行事实','contextConfirm')}<button>提交员工确认意图</button></form>`:'<p data-context-confirm-empty>当前无待核对基础条目</p>'}<p>加入待核对不等于确认。此操作单独保留员工核查原话，须后端复核，不改变原模型来源或实际操作。</p></section></div>`;}
    if(step===2){const groups=view.native.zones[zone].groups;return `<div class="apw-zone-bar">${DESIGN_ZONES.map((z,i)=>`<button data-zone="${z}" aria-pressed="${zone===z}">${zoneNames[i]}</button>`).join('')}</div>${neutral()}<div class="adp-actions">${Object.keys(serviceFields).map(s=>`<label><input type="checkbox" data-service="${s}"${hidden.has(s)?'':' checked'}>${s==='perm'?'烫发':s==='dye'?'染发':'剪发'}</label>`).join('')}</div><form data-command="create_group"><label>项目<select name="service"><option value="perm">烫发</option><option value="dye">染发</option><option value="cut">剪发</option></select></label><label>明确左右<select name="side">${['unknown','left','right','center','bilateral'].map(s=>option(s,{unknown:'未知',left:'左侧',right:'右侧',center:'中线',bilateral:'明确双侧'}[s])).join('')}</select></label><button>添加独立工艺组</button></form>${groups.filter(g=>!hidden.has(g.service)).map(g=>`<section class="apw-group" data-group-card="${E(g.groupId)}"><h3>${E(g.service)} · ${E(g.side)} · ${E(g.groupId)}</h3><div class="apw-tracks">${['planned','actual'].map(t=>`<article class="apw-track"><h4>${t==='planned'?'拟执行':'实际记录'}</h4>${view.native.entries.filter(e=>e.groupId===g.groupId&&e.track===t).map(entryCard).join('')||'<p>待确认，无记录</p>'}</article>`).join('')}</div>${entryForm('technique',g)}</section>`).join('')}<section class="adp-card"><h3>独立确认意图</h3><form data-command="confirm_entry"><label>待核对条目<select name="entryId">${view.native.entries.filter(e=>e.category==='technique'&&e.zone===zone&&e.value!==null&&e.status!=='confirmed').map(e=>option(e.id,`${e.groupId} ${e.track} ${fieldNames[e.field]}: ${e.value}`)).join('')}</select></label>${textarea('confirmText','写明本人确认的值，保留为独立原话')}<button>提交员工确认意图</button></form><p>界面不会乐观改成已确认，须后端完成权限复核并返回。</p></section>`;}
    if(step===3)return `<section class="adp-card"><h3>完成后复盘</h3><p>实际结果需要独立来源，不复制计划。模型完成照描述与员工观察分别保留；采纳不等于确认，不推断化学原因或工艺达标。</p>${entryForm('review')}<section data-review-records>${view.native.entries.filter(e=>e.category==='result_review').map(entryCard).join('')}</section><form data-command="record_note"><input type="hidden" name="field" value="care">${textarea('noteText','完成后打理原始备注（仍未映射）')}<button>保留完成后备注</button></form><form data-command="confirm_entry"><label>独立核对复盘条目<select name="entryId">${view.native.entries.filter(e=>e.category==='result_review'&&e.value!==null&&e.status!=='confirmed').map(e=>option(e.id,`${fieldNames[e.field]||e.field}: ${e.value}`)).join('')}</select></label>${textarea('confirmText','写明本人核对的值；不把模型判断改称客观测量','reviewConfirm')}<button>提交员工确认意图</button></form></section>${privatePhotoPairs()}${modelPanel(true)}${modelPanel('synthesis')}${managedViewsPanel()}${applicationViewsPanel()}`;
    return `<section class="adp-card"><h3>不可覆盖的本机验收记录</h3><div data-archive-versions></div><p>原始来源 ${view.native.sources.length} 条；原生修订 ${view.record.session.revision}；归档 ${view.record.archives.length} 份。未写入生产云档案。</p><button data-action="archive"${view.native.phase!=='completed_review'?' disabled':''}>追加原生归档检查点</button><button data-action="snapshot">准备完整档案候选</button>${view.record.archives.map(a=>`<p data-archive>原生归档 revision ${a.revision}，父档 ${a.previousArchiveRevision??'无'}</p>`).join('')}${view.candidate?`<p data-snapshot>${view.candidate.schemaVersion==='design-workflow-snapshot-preview-v1'?'已准备档案安全预览（完整内容由服务端构建）':'已准备完整候选'} ${E(view.candidate.schemaVersion==='design-workflow-snapshot-preview-v1'?view.candidate.sourceDigest:view.candidate.snapshot.sha256)}；saved=false，尚需可信来源与完整事务核查。</p>`:''}${view.canArchive?`<section><button data-action="full-history">读取完整档案版本</button>${view.history?`<p data-full-head>后端当前完整版本 ${view.history.currentVersion}</p>`:''}<button data-action="full-save"${!view.history||!view.candidate||view.archiveBusy||view.archivePending?' disabled':''}>明确提交完整档案</button>${view.archivePending?'<button data-action="full-retry">核对后重试同一完整档案请求</button>':''}${view.archiveSaved?`<p data-full-saved>完整档案后端确认保存版本 ${view.archiveSaved.appliedVersion}（当前验收环境）</p>`:''}<p>原生检查点不是完整档案保存成功；以后端完整事务返回为准。</p></section>`:''}${view.native.phase==='archive'?`<form data-command="reopen">${textarea('reason','新修订理由')}<label>恢复阶段<select name="resumePhase"><option value="proposal">拟执行方案</option><option value="execution">实际执行</option><option value="completed_review">完成复盘</option></select></label><button>保留旧档，开启新修订</button></form>`:''}</section>`;
  }
  function render(){if(destroyed)return;texts=[];if(enabled!==true||!adapter){container.innerHTML='<section class="adp apw"><div class="adp-shell"><h1>设计记录 · 接口准备版</h1><p class="adp-safety">默认关闭：未配置经审核的员工、顾客、来源和事务后端。本页不接受真实资料，不连接麦克风、模型或密钥。</p></div></section>';return;}
    container.innerHTML=`<section class="adp apw"><div class="adp-shell"><header><p class="adp-eyebrow">PREPARED · OFFLINE ACCEPTANCE</p><h1>设计记录 · 接口准备版</h1><p class="adp-safety">尚未生产上线。本次只用合成资料验收真实输入路径；无 AI 自动解析、收费调用或真实顾客素材；音频验收只用合成流。</p></header><label>当前顾客候选（服务端逐次核权）<select data-customer>${customers.map(c=>option(c.id,c.title,view.selected)).join('')}</select></label>${view.record?`${view.record.schemaVersion==='design-prepared-workflow-record-v5'?`<p class="adp-safety" data-normalized-record-notice>${E(NORMALIZED_SYNTHETIC_NOTICE)}</p>`:''}<div class="adp-connected-bar"><strong>记录 revision ${view.record.revision} · ${phaseNames[DESIGN_PHASES.indexOf(view.native.phase)]}${view.busy?' · 请求中':''}</strong>${view.error?`<p class="apw-error" role="alert">${E(view.error)}，输入仍保留。结果不确定时勿创建新请求。</p>`:''}<button data-action="reload">重新读取</button>${view.pending?'<button data-action="retry">重试同一请求</button><button data-action="discard">明确放弃待处理意图并重读</button>':''}${view.native.phase!=='archive'&&view.native.phase!=='completed_review'?`<button data-action="advance">明确进入下一阶段</button>`:''}</div><nav class="adp-stepper">${steps.map((label,i)=>`<button data-step="${i}" aria-current="${step===i?'step':'false'}">${i+1}. ${label}</button>`).join('')}</nav><fieldset${view.busy||view.pending||view.archiveBusy?' disabled':''}>${content()}</fieldset>`:`<p>${view.busy?'加载中…':view.error||'请选择合成验收顾客'}</p><button data-action="reload">重新核权读取</button>`}</div></section>`;
    container.querySelectorAll('textarea[data-draft]').forEach(node=>{node.value=draft()[node.dataset.draft]||'';});
    container.querySelectorAll('[data-raw]').forEach(node=>{node.textContent=texts[Number(node.dataset.raw)];});
    const archiveView=container.querySelector('[data-archive-versions]');if(archiveView&&view.record)renderArchiveVersions(archiveView,{scope:view.scope,legacyVersions:view.record.legacyVersions,history:view.history,browserViews:view.record.schemaVersion==='design-workflow-view-v1'});
  }
  const unsub=controller.subscribe(next=>{view=next;render();});
  const events=new AbortController();
  if(enabled!==true||!adapter)return Object.freeze({controller,destroy(){destroyed=true;unsub();controller.destroy();container.replaceChildren();}});
  const error=e=>{view={...view,error:e.code||e.message};render();};
  container.addEventListener('input',event=>{if(event.target.dataset.draft)draft()[event.target.dataset.draft]=event.target.value;},{signal:events.signal});
  container.addEventListener('change',event=>{if(event.target.matches('[data-managed-file]')&&event.target.files[0]){controller.selectManagedImage(event.target.files[0],container.querySelector('[data-managed-stage]').value,container.querySelector('[data-managed-angle]').value).catch(error);}if(event.target.matches('[data-photo-file]')&&event.target.files[0]){const stage=container.querySelector('[data-photo-stage]').value,angle=container.querySelector('[data-photo-angle]').value;controller.selectPhoto(event.target.files[0],stage,angle).catch(error);}if(event.target.dataset.draft)draft()[event.target.dataset.draft]=event.target.value;if(event.target.matches('[data-model-before],[data-model-after],[data-model-side],[data-managed-view-before],[data-managed-view-after],[data-managed-view-side],[data-application-view-before],[data-application-view-after],[data-application-view-side]'))render();if(event.target.matches('[data-customer]')){const c=customers.find(c=>c.id===event.target.value);step=0;controller.select(c.id,c.scope).catch(error);}if(event.target.dataset.service){event.target.checked?hidden.delete(event.target.dataset.service):hidden.add(event.target.dataset.service);render();}},{signal:events.signal});
  container.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.step!==undefined){step=Number(button.dataset.step);render();}if(button.dataset.zone){zone=button.dataset.zone;render();}const action=button.dataset.action;if(!action)return;const tasks={'application-view-prepare':()=>controller.prepareApplicationView(button.dataset.mediaId),'application-view-prepare-status':()=>controller.checkApplicationViewPreparation(),'application-view-compare':()=>controller.requestApplicationViews('compare',{beforeTaskId:container.querySelector('[data-application-view-before]')?.value,afterTaskId:container.querySelector('[data-application-view-after]')?.value}),'application-view-synthesize':()=>controller.requestApplicationViews('synthesize',{side:container.querySelector('[data-application-view-side]')?.value}),'application-view-status':()=>controller.checkApplicationViews(),'application-model-describe':()=>controller.requestApplicationModel(),'application-model-status':()=>controller.checkApplicationModel(),'application-prepare':()=>controller.prepareApplicationImage(button.dataset.mediaId),'application-prepare-status':()=>controller.checkApplicationPreparation(),'normalized-describe':()=>controller.requestNormalizedSynthetic(container.querySelector('[data-normalized-task]')?.value),'normalized-check':()=>controller.checkNormalizedSynthetic(container.querySelector('[data-normalized-request-id]')?.value||null),'normalized-abandon':()=>{if(window.confirm('仅停止本页追踪，不取消服务器请求，也不证明未执行。请先保存原请求编号。继续？'))controller.abandonNormalizedSynthetic();},'managed-view-verify':()=>controller.readManagedView(container.querySelector('[data-managed-view-task]').value),'managed-view-describe':()=>controller.requestManagedView('describe',button.dataset.taskId),'managed-view-compare':()=>controller.requestManagedView('compare',{beforeTaskId:container.querySelector('[data-managed-view-before]')?.value,afterTaskId:container.querySelector('[data-managed-view-after]')?.value}),'managed-view-synthesize':()=>controller.requestManagedView('synthesize',container.querySelector('[data-managed-view-side]')?.value),'managed-view-check':()=>controller.checkManagedView(container.querySelector('[data-managed-view-request-id]')?.value||null),'managed-view-abandon':()=>{if(window.confirm('这只停止本页追踪，不取消服务器请求或费用。保留原编号后继续？'))controller.abandonManagedView();},'managed-verification':()=>controller.readManagedVerification(container.querySelector('[data-managed-task]').value),'managed-describe':()=>controller.requestManagedModel(),'managed-model-check':()=>controller.checkManagedModel(container.querySelector('[data-managed-model-request-id]')?.value||null),'managed-model-abandon':()=>{if(window.confirm('这只停止本页追踪，不取消服务器请求或费用。保留原请求编号后继续？'))controller.abandonManagedModel();},'managed-upload':()=>controller.uploadManagedImage(),'managed-clear':()=>controller.clearManagedSelection(),'managed-status':()=>view.canApplicationContent?controller.readApplicationImage(container.querySelector('[data-managed-lookup]')?.value||null,false,container.querySelector('[data-application-request]')?.value||null):controller.readManagedImage(container.querySelector('[data-managed-lookup]')?.value||null),'application-reconcile':()=>{if(window.confirm('只核对原请求对象并尝试恢复原回执，不重新上传图片。继续？'))return controller.reconcileApplicationImage();},'synthesis-list':()=>controller.listSynthesis(),'synthesis-check':()=>controller.checkSynthesis(),'synthesis-resume':()=>controller.checkSynthesis(button.dataset.operationId),'synthesis-cancel':()=>{if(window.confirm('仅请求停止尚未发送的后续执行。已发送请求不能撤回，仍可能完成或收费；以服务端核查结果为准。继续？'))return controller.cancelSynthesis();},'model-abandon':()=>{if(window.confirm('原请求可能已完成或产生费用。这只停止本页重试并保留原编号，不取消服务端调用。后续新请求仍需独立批准。确定继续？'))controller.abandonModelRequest();},'model-extract':()=>controller.requestModel('extract'),'model-synthesize':()=>controller.requestModel('synthesize',container.querySelector('[data-model-side]')?.value),'model-compare':()=>controller.requestModel('compare',{beforeMediaId:container.querySelector('[data-model-before]')?.value,afterMediaId:container.querySelector('[data-model-after]')?.value}),'model-vision':()=>controller.requestModel('vision',container.querySelector('[data-model-media]')?.value),'model-retry':()=>controller.retryModel(),reload:()=>controller.load(),discard:()=>controller.load({discardPending:true}),retry:()=>controller.retry(),transcript:()=>controller.requestTranscript(),'accept-transcript':()=>controller.acceptTranscript(),advance:()=>controller.send({type:'advance',phase:DESIGN_PHASES[DESIGN_PHASES.indexOf(view.native.phase)+1]}),archive:()=>controller.send({type:'archive'}),snapshot:()=>controller.buildSnapshot(),'photo-upload':()=>controller.uploadPhoto(),'photo-retry':()=>controller.retryUpload(),'photo-attach':()=>controller.send({type:'attach_media',mediaIds:[view.uploaded.mediaId]}),'record-start':()=>controller.startCapture(),'record-stop':()=>controller.stopCapture(),'record-cancel':()=>controller.cancelCapture(),'record-submit':()=>controller.submitRecording(),preview:()=>controller.preview(button.dataset.mediaId),'full-history':()=>controller.loadHistory(),'full-save':()=>controller.saveFullArchive(),'full-retry':()=>controller.retryFullArchive()};Promise.resolve().then(tasks[action]).catch(error);},{signal:events.signal});
  container.addEventListener('submit',event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form)),type=form.dataset.command;let intent;
    if(type==='accept_application_view_candidate'){controller.acceptApplicationView(Array.from(form.querySelectorAll('[data-application-view-index]:checked'),input=>Number(input.dataset.applicationViewIndex))).catch(error);return;}
    if(type==='accept_application_candidate'){controller.acceptApplicationModel(Array.from(form.querySelectorAll('[data-application-index]:checked'),input=>Number(input.dataset.applicationIndex))).catch(error);return;}
    if(type==='accept_normalized_candidate'){controller.acceptNormalizedSynthetic(Array.from(form.querySelectorAll('[data-normalized-index]:checked'),input=>Number(input.dataset.normalizedIndex))).catch(error);return;}
    if(type==='accept_managed_view_candidate'){controller.acceptManagedView(Array.from(form.querySelectorAll('[data-managed-view-index]:checked'),input=>Number(input.dataset.managedViewIndex))).catch(error);return;}
    if(type==='accept_managed_candidate'){controller.acceptManagedModel(Array.from(form.querySelectorAll('[data-managed-model-index]:checked'),input=>Number(input.dataset.managedModelIndex))).catch(error);return;}
    if(type==='accept_model_candidate'){controller.acceptModel(Array.from(form.querySelectorAll('[data-model-index]:checked'),input=>Number(input.dataset.modelIndex))).catch(error);return;}
    if(type==='record_source')intent={type,kind:data.kind,text:data.sourceText};
    else if(type==='record_note')intent={type,field:data.field,text:data.noteText};
    else if(type==='create_group')intent={type,zone,service:data.service,side:data.side};
    else if(['record_context','record_technique','record_review'].includes(type)){const category=type==='record_context'?'person_style':type==='record_review'?'result_review':'technique',track=category==='person_style'?'context':category==='result_review'?'actual':data.track;let value;try{value=parsePreparedEntryValue(data.field,data.entryValue);}catch(e){error(e);return;}const previous=view.native.entries.find(e=>e.category===category&&e.field===data.field&&e.track===track&&(category!=='technique'||e.groupId===form.dataset.group));intent={type,field:data.field,value,sourceId:value===null?null:data.sourceId,quote:value===null?null:data.entryQuote,replacesEntryId:previous?.id??null,...(category==='technique'?{groupId:form.dataset.group,track}:{} )};}
    else if(type==='confirm_entry')intent={type,entryId:data.entryId,text:data.confirmText};else if(type==='attach_media')intent={type,mediaIds:[data.mediaId]};else if(type==='reopen')intent={type,resumePhase:data.resumePhase,reason:data.reason};
    controller.send(intent).catch(error);
  },{signal:events.signal});
  window.addEventListener('pagehide',()=>controller.suspend(),{signal:events.signal});
  window.addEventListener('pageshow',event=>{if(event.persisted)controller.resume()?.catch(error);},{signal:events.signal});
  if(enabled&&adapter&&customers.length)controller.select(customers[0].id,customers[0].scope).catch(error);
  return Object.freeze({controller,destroy(){destroyed=true;events.abort();unsub();controller.destroy();container.replaceChildren();}});
}
const root=typeof document==='undefined'?null:document.getElementById('prepared-root');if(root)mountPreparedDesign(root);
